11	#include <cstdio>
12	#include <cstdlib>
13	#include <cstring>
14	#include <string>
15	#include <vector>
16	#include "acl/acl.h"
17	#include "hixl/hixl.h"
18	
19	using namespace hixl;
20	namespace {
21	constexpr size_t kXferBufSize = 8 * 1024 * 1024;
22	constexpr size_t kXferBlockSize = 16 * 1024;
23	constexpr size_t kXferBlockCount = kXferBufSize / kXferBlockSize;
24	constexpr int32_t kDefaultDevA = 0;
25	constexpr int32_t kDefaultDevB = 2;
26	constexpr int32_t kVersionLegacy = 0;
27	constexpr const char *kEngineA = "127.0.0.1:16000";
28	constexpr const char *kEngineB = "127.0.0.1:16001";
29	constexpr uint8_t kFillA = 0xAA;
30	constexpr uint8_t kFillB = 0xBB;
31	constexpr int32_t kConnTimeout = 5000;
32	constexpr int32_t kXferTimeout = 30000;
33	static const std::vector<std::string> kValidProtos = {"roce:device", "roce:host", "uboe:device", "ub_rtp:device",
34	                                                      "ub_ctp:device"};
35	
36	#define CHECK_ACL(x)                                                                      \
37	  do {                                                                                    \
38	    aclError __acl_ret = x;                                                               \
39	    if (__acl_ret != ACL_ERROR_NONE) {                                                    \
40	      std::cerr << __FILE__ << ":" << __LINE__ << " aclError:" << __acl_ret << std::endl; \
41	    }                                                                                     \
42	  } while (0)
43	
44	struct EngineCtx {
45	  Hixl engine;
46	  int32_t device_id = 0;
47	  const char *name = nullptr;
48	  bool initialized = false;
49	  bool connected = false;
50	  void *dev_buf = nullptr;
51	  MemHandle dev_handle = nullptr;
52	};
53	
54	const char *GetRecentErrMsg() {
55	  const char *msg = aclGetRecentErrMsg();
56	  return (msg == nullptr) ? "no error" : msg;
57	}
58	
59	void SplitProtocolString(const std::string &input, std::vector<std::string> &out) {
60	  size_t begin = 0;
61	  size_t comma = input.find(',');
62	  while (comma != std::string::npos) {
63	    out.push_back(input.substr(begin, comma - begin));
64	    begin = comma + 1;
65	    comma = input.find(',', begin);
66	  }
67	  out.push_back(input.substr(begin));
68	}
69	
70	int32_t CheckProtocolValidity(const std::string &proto) {
71	  for (const auto &p : kValidProtos) {
72	    if (p == proto) {
73	      return 0;
74	    }
75	  }
76	  printf("[ERROR] Invalid protocol: %s\n", proto.c_str());
77	  printf("Supported:");
78	  for (const auto &p : kValidProtos) {
79	    printf(" %s", p.c_str());
80	  }
81	  printf("\n");
82	  return -1;
83	}
84	
85	int32_t ParseArgs(int32_t argc, char **argv, int32_t &device_a, int32_t &device_b, std::vector<std::string> &protocols,
86	                  int32_t &version) {
87	  for (int32_t i = 1; i < argc; ++i) {
88	    std::string arg = argv[i];
89	    if (arg.find("--device=") == 0) {
90	      std::string val = arg.substr(9);
91	      auto pos = val.find(',');
92	      if (pos == std::string::npos) {
93	        printf("[ERROR] Invalid --device format, expected id1,id2\n");
94	        return -1;
95	      }
96	      device_a = std::stoi(val.substr(0, pos));
97	      device_b = std::stoi(val.substr(pos + 1));
98	    } else if (arg.find("--protocol=") == 0) {
99	      SplitProtocolString(arg.substr(11), protocols);
100	    } else if (arg.find("--version=") == 0) {
101	      version = std::stoi(arg.substr(10));
102	    } else {
103	      printf("[ERROR] Unknown argument: %s\n", arg.c_str());
104	      printf("Usage: %s --protocol=<type>[,...] [--device=id1,id2] [--version=0|1]\n", argv[0]);
105	      return -1;
106	    }
107	  }
108	
109	  if (protocols.empty()) {
110	    printf("[ERROR] --protocol is required\n");
111	    printf("Usage: %s --protocol=<type>[,...] [--device=id1,id2] [--version=0|1]\n", argv[0]);
112	    return -1;
113	  }
114	
115	  for (const auto &p : protocols) {
116	    if (CheckProtocolValidity(p) != 0) {
117	      return -1;
118	    }
119	  }
120	
121	  if (version == kVersionLegacy) {
122	    if (protocols.size() != 1 || protocols[0] != "roce:device") {
123	      printf("[ERROR] version 0 only supports roce:device\n");
124	      return -1;
125	    }
126	  }
127	
128	  printf("[INFO] ParseArgs success: device_a=%d, device_b=%d, version=%d\n", device_a, device_b, version);
129	  for (const auto &p : protocols) {
130	    printf("[INFO]   protocol: %s\n", p.c_str());
131	  }
132	  return 0;
133	}
134	
135	int32_t ConfigLegacyOptions(EngineCtx &ctx, const std::vector<std::string> &protocols,
136	                            std::map<AscendString, AscendString> &options) {
137	  printf("[INFO] %s using legacy flow (version=0)\n", ctx.name);
138	  std::string engine_name(ctx.name);
139	  size_t colon_pos = engine_name.find(':');
140	  uint32_t port = std::stoi(engine_name.substr(colon_pos + 1));
141	  std::string comm_res = "{\"version\": \"1.2\"}";
142	  options[OPTION_LOCAL_COMM_RES] = comm_res.c_str();
143	  std::string config = "{\"comm_resource_config.listen_port\": " + std::to_string(port) + "}";
144	  options[OPTION_GLOBAL_RESOURCE_CONFIG] = config.c_str();
145	  options[OPTION_BUFFER_POOL] = "0:0";
146	  if (protocols[0] == "roce:device") {
147	    setenv("HCCL_INTRA_ROCE_ENABLE", "1", 1);
148	  }
149	  return 0;
150	}
151	
152	int32_t ConfigV2Options(const std::vector<std::string> &protocols, std::map<AscendString, AscendString> &options) {
153	  std::string desc_array;
154	  for (size_t i = 0; i < protocols.size(); ++i) {
155	    if (i > 0) {
156	      desc_array += ",";
157	    }
158	    desc_array += "\"" + protocols[i] + "\"";
159	  }
160	  std::string config = "{\"comm_resource_config.protocol_desc\": [" + desc_array + "]}";
161	  options[OPTION_GLOBAL_RESOURCE_CONFIG] = config.c_str();
162	  return 0;
163	}
164	
165	int32_t InitEngine(EngineCtx &ctx, const std::vector<std::string> &protocols, int32_t version, uint8_t fill_value) {
166	  CHECK_ACL(aclrtSetDevice(ctx.device_id));
167	  std::map<AscendString, AscendString> options;
168	  if (version == kVersionLegacy) {
169	    ConfigLegacyOptions(ctx, protocols, options);
170	  } else {
171	    ConfigV2Options(protocols, options);
172	  }
173	  auto ret = ctx.engine.Initialize(ctx.name, options);
174	  if (ret != SUCCESS) {
175	    printf("[ERROR] Initialize %s failed, ret=%u, errmsg:%s\n", ctx.name, ret, GetRecentErrMsg());
176	    return -1;
177	  }
178	  ctx.initialized = true;
179	  printf("[INFO] InitEngine %s success\n", ctx.name);
180	  uint8_t *dev_ptr = nullptr;
181	  CHECK_ACL(aclrtMalloc(reinterpret_cast<void **>(&dev_ptr), kXferBufSize, ACL_MEM_MALLOC_HUGE_ONLY));
182	  ctx.dev_buf = dev_ptr;
183	  MemDesc desc{};
184	  desc.addr = reinterpret_cast<uintptr_t>(ctx.dev_buf);
185	  desc.len = kXferBufSize;
186	  ret = ctx.engine.RegisterMem(desc, MEM_DEVICE, ctx.dev_handle);
187	  if (ret != SUCCESS) {
188	    printf("[ERROR] %s RegisterMem device failed, ret=%u, errmsg:%s\n", ctx.name, ret, GetRecentErrMsg());
189	    return -1;
190	  }
191	  std::vector<uint8_t> host_tmp(kXferBufSize, fill_value);
192	  CHECK_ACL(aclrtMemcpy(ctx.dev_buf, kXferBufSize, host_tmp.data(), kXferBufSize, ACL_MEMCPY_HOST_TO_DEVICE));
193	  printf("[INFO] %s InitEngine success, dev:%p\n", ctx.name, ctx.dev_buf);
194	  return 0;
195	}
196	
197	int32_t Connect(EngineCtx &ctx_a, EngineCtx &ctx_b) {
198	  auto ret = ctx_a.engine.Connect(ctx_b.name, kConnTimeout);
199	  if (ret != SUCCESS) {
200	    printf("[ERROR] Connect %s->%s failed, ret=%u, errmsg:%s\n", ctx_a.name, ctx_b.name, ret, GetRecentErrMsg());
201	    return -1;
202	  }
203	  ctx_a.connected = true;
204	  printf("[INFO] Connect success\n");
205	  return 0;
206	}
207	
208	int32_t Transfer(EngineCtx &ctx_a, EngineCtx &ctx_b) {
209	  std::vector<TransferOpDesc> descs;
210	  descs.reserve(kXferBlockCount);
211	  for (size_t i = 0; i < kXferBlockCount; ++i) {
212	    TransferOpDesc desc{};
213	    desc.local_addr = reinterpret_cast<uintptr_t>(ctx_a.dev_buf) + i * kXferBlockSize;
214	    desc.remote_addr = reinterpret_cast<uintptr_t>(ctx_b.dev_buf) + i * kXferBlockSize;
215	    desc.len = kXferBlockSize;
216	    descs.push_back(desc);
217	  }
218	  auto ret = ctx_a.engine.TransferSync(ctx_b.name, WRITE, descs, kXferTimeout);
219	  if (ret != SUCCESS) {
220	    printf("[ERROR] TransferSync %s->%s failed, ret=%u, errmsg:%s\n", ctx_a.name, ctx_b.name, ret, GetRecentErrMsg());
221	    return -1;
222	  }
223	  printf("[INFO] Transfer completed\n");
224	  return 0;
225	}
226	
227	int32_t Verify(EngineCtx &ctx_b) {
228	  void *host_tmp = nullptr;
229	  CHECK_ACL(aclrtMallocHost(&host_tmp, kXferBufSize));
230	  CHECK_ACL(aclrtMemcpy(host_tmp, kXferBufSize, ctx_b.dev_buf, kXferBufSize, ACL_MEMCPY_DEVICE_TO_HOST));
231	  std::vector<uint8_t> expected(kXferBufSize, kFillA);
232	  if (std::memcmp(host_tmp, expected.data(), kXferBufSize) != 0) {
233	    printf("[ERROR] Verify %s dev_buf failed, expected 0xAA\n", ctx_b.name);
234	    CHECK_ACL(aclrtFreeHost(host_tmp));
235	    return -1;
236	  }
237	  CHECK_ACL(aclrtFreeHost(host_tmp));
238	  printf("[INFO] Verify success\n");
239	  return 0;
240	}
241	
242	void Finalize(EngineCtx &ctx_a, EngineCtx &ctx_b) {
243	  if (ctx_a.connected) {
244	    auto ret = ctx_a.engine.Disconnect(ctx_b.name, kConnTimeout);
245	    if (ret != SUCCESS) {
246	      printf("[ERROR] Disconnect %s->%s failed, ret=%u, errmsg:%s\n", ctx_a.name, ctx_b.name, ret, GetRecentErrMsg());
247	    } else {
248	      printf("[INFO] Disconnect success\n");
249	    }
250	  }
251	  if (ctx_a.dev_handle != nullptr) {
252	    ctx_a.engine.DeregisterMem(ctx_a.dev_handle);
253	  }
254	  if (ctx_b.dev_handle != nullptr) {
255	    ctx_b.engine.DeregisterMem(ctx_b.dev_handle);
256	  }
257	  if (ctx_a.dev_buf != nullptr) {
258	    CHECK_ACL(aclrtFree(ctx_a.dev_buf));
259	  }
260	  if (ctx_b.dev_buf != nullptr) {
261	    CHECK_ACL(aclrtFree(ctx_b.dev_buf));
262	  }
263	  if (ctx_a.initialized) {
264	    ctx_a.engine.Finalize();
265	  }
266	  if (ctx_b.initialized) {
267	    ctx_b.engine.Finalize();
268	  }
269	  CHECK_ACL(aclrtResetDevice(ctx_a.device_id));
270	  CHECK_ACL(aclrtResetDevice(ctx_b.device_id));
271	}
272	
273	int32_t Run(EngineCtx &ctx_a, EngineCtx &ctx_b, const std::vector<std::string> &protocols, int32_t version) {
274	  if (InitEngine(ctx_a, protocols, version, kFillA) != 0) {
275	    return -1;
276	  }
277	  if (InitEngine(ctx_b, protocols, version, kFillB) != 0) {
278	    return -1;
279	  }
280	  if (Connect(ctx_a, ctx_b) != 0) {
281	    return -1;
282	  }
283	  if (Transfer(ctx_a, ctx_b) != 0) {
284	    return -1;
285	  }
286	  return Verify(ctx_b);
287	}
288	}  // namespace
289	
290	int main(int32_t argc, char **argv) {
291	  int32_t device_a = kDefaultDevA;
292	  int32_t device_b = kDefaultDevB;
293	  std::vector<std::string> protocols;
294	  int32_t version = 1;
295	  if (ParseArgs(argc, argv, device_a, device_b, protocols, version) != 0) {
296	    return -1;
297	  }
298	  EngineCtx ctx_a;
299	  EngineCtx ctx_b;
300	  ctx_a.device_id = device_a;
301	  ctx_a.name = kEngineA;
302	  ctx_b.device_id = device_b;
303	  ctx_b.name = kEngineB;
304	  int32_t ret = Run(ctx_a, ctx_b, protocols, version);
305	  Finalize(ctx_a, ctx_b);
306	  return ret;
307	}
