21	using namespace hixl;
22	namespace {
23	constexpr size_t kBufferSize = 8 * 1024 * 1024;
24	constexpr size_t kChunkSize = 16 * 1024;
25	constexpr size_t kChunkCount = kBufferSize / kChunkSize;
26	constexpr int32_t kDefaultDevA = 0;
27	constexpr int32_t kDefaultDevB = 2;
28	constexpr int32_t kVersionLegacy = 0;
29	constexpr const char *kEngineA = "127.0.0.1:16000";
30	constexpr const char *kEngineB = "127.0.0.1:16001";
31	constexpr uint8_t kFillA = 0xAA;
32	constexpr uint8_t kFillB = 0xBB;
33	constexpr int32_t kConnTimeout = 5000;
34	constexpr int32_t kMaxPollCount = 100000;
35	static const std::vector<std::string> kSupportedProtocols = {"roce:device",   "roce:host",     "uboe:device",
36	                                                             "ub_rtp:device", "ub_ctp:device", "ub_ctp:host"};
37	
38	#define CHECK_ACL(x)                                                                       \
39	  do {                                                                                     \
40	    aclError __err_code = x;                                                               \
41	    if (__err_code != ACL_ERROR_NONE) {                                                    \
42	      std::cerr << __FILE__ << ":" << __LINE__ << " aclError:" << __err_code << std::endl; \
43	    }                                                                                      \
44	  } while (0)
45	
46	struct EngineCtx {
47	  Hixl engine;
48	  int32_t device_id = 0;
49	  const char *name = nullptr;
50	  bool initialized = false;
51	  bool connected = false;
52	  void *dev_buf = nullptr;
53	  void *host_buf = nullptr;
54	  MemHandle dev_handle = nullptr;
55	  MemHandle host_handle = nullptr;
56	};
57	
58	const char *GetRecentErrMsg() {
59	  const char *errmsg = aclGetRecentErrMsg();
60	  return (errmsg == nullptr) ? "no error" : errmsg;
61	}
62	
63	void TokenizeProtocols(const std::string &val, std::vector<std::string> &protocols) {
64	  size_t start = 0;
65	  size_t pos = val.find(',');
66	  while (pos != std::string::npos) {
67	    protocols.push_back(val.substr(start, pos - start));
68	    start = pos + 1;
69	    pos = val.find(',', start);
70	  }
71	  protocols.push_back(val.substr(start));
72	}
73	
74	int32_t VerifyProtocolSupport(const std::string &proto) {
75	  for (const auto &item : kSupportedProtocols) {
76	    if (item == proto) {
77	      return 0;
78	    }
79	  }
80	  printf("[ERROR] Invalid protocol: %s\n", proto.c_str());
81	  printf("Supported:");
82	  for (const auto &item : kSupportedProtocols) {
83	    printf(" %s", item.c_str());
84	  }
85	  printf("\n");
86	  return -1;
87	}
88	
89	int32_t ParseArgs(int32_t argc, char **argv, int32_t &device_a, int32_t &device_b, std::vector<std::string> &protocols,
90	                  int32_t &version) {
91	  for (int32_t i = 1; i < argc; ++i) {
92	    std::string arg = argv[i];
93	    if (arg.find("--device=") == 0) {
94	      std::string device_str = arg.substr(9);
95	      auto comma_pos = device_str.find(',');
96	      if (comma_pos == std::string::npos) {
97	        printf("[ERROR] Invalid --device format, expected id1,id2\n");
98	        return -1;
99	      }
100	      device_a = std::stoi(device_str.substr(0, comma_pos));
101	      device_b = std::stoi(device_str.substr(comma_pos + 1));
102	    } else if (arg.find("--protocol=") == 0) {
103	      TokenizeProtocols(arg.substr(11), protocols);
104	    } else if (arg.find("--version=") == 0) {
105	      version = std::stoi(arg.substr(10));
106	    } else {
107	      printf("[ERROR] Unknown argument: %s\n", arg.c_str());
108	      printf("Usage: %s --protocol=<type>[,...] [--device=id1,id2] [--version=0|1]\n", argv[0]);
109	      return -1;
110	    }
111	  }
112	
113	  if (protocols.empty()) {
114	    printf("[ERROR] --protocol is required\n");
115	    return -1;
116	  }
117	
118	  for (const auto &proto : protocols) {
119	    if (VerifyProtocolSupport(proto) != 0) {
120	      return -1;
121	    }
122	  }
123	
124	  bool is_legacy = (version == kVersionLegacy);
125	  bool single_roce = (protocols.size() == 1 && protocols[0] == "roce:device");
126	  if (is_legacy && !single_roce) {
127	    printf("[ERROR] version 0 only supports roce:device\n");
128	    return -1;
129	  }
130	
131	  printf("[INFO] ParseArgs success: device_a=%d, device_b=%d, version=%d\n", device_a, device_b, version);
132	  for (const auto &proto : protocols) {
133	    printf("[INFO]   protocol: %s\n", proto.c_str());
134	  }
135	  return 0;
136	}
137	
138	int32_t BuildLegacyConfig(EngineCtx &ctx, const std::vector<std::string> &protocols,
139	                          std::map<AscendString, AscendString> &options) {
140	  printf("[INFO] %s using legacy flow (version=0)\n", ctx.name);
141	  std::string eng_name(ctx.name);
142	  auto sep = eng_name.find(':');
143	  uint32_t listen_port = std::stoi(eng_name.substr(sep + 1));
144	  std::string lcomm = "{\"version\": \"1.2\"}";
145	  options[OPTION_LOCAL_COMM_RES] = lcomm.c_str();
146	  std::string res_cfg = "{\"comm_resource_config.listen_port\": " + std::to_string(listen_port) + "}";
147	  options[OPTION_GLOBAL_RESOURCE_CONFIG] = res_cfg.c_str();
148	  if (protocols[0] == "roce:device") {
149	    options[OPTION_BUFFER_POOL] = "0:0";
150	    setenv("HCCL_INTRA_ROCE_ENABLE", "1", 1);
151	  }
152	  return 0;
153	}
154	
155	int32_t BuildV2Config(const std::vector<std::string> &protocols, std::map<AscendString, AscendString> &options) {
156	  std::string proto_list;
157	  bool first = true;
158	  for (const auto &proto : protocols) {
159	    if (!first) {
160	      proto_list += ",";
161	    }
162	    proto_list += "\"" + proto + "\"";
163	    first = false;
164	  }
165	  std::string res_config = "{\"comm_resource_config.protocol_desc\": [" + proto_list + "]}";
166	  options[OPTION_GLOBAL_RESOURCE_CONFIG] = res_config.c_str();
167	  return 0;
168	}
169	
170	int32_t InitEngine(EngineCtx &ctx, const std::vector<std::string> &protocols, int32_t version, uint8_t fill_value) {
171	  CHECK_ACL(aclrtSetDevice(ctx.device_id));
172	  std::map<AscendString, AscendString> options;
173	  if (version == kVersionLegacy) {
174	    BuildLegacyConfig(ctx, protocols, options);
175	  } else {
176	    BuildV2Config(protocols, options);
177	  }
178	  auto ret = ctx.engine.Initialize(ctx.name, options);
179	  if (ret != SUCCESS) {
180	    printf("[ERROR] Initialize %s failed, ret=%u, errmsg:%s\n", ctx.name, ret, GetRecentErrMsg());
181	    return -1;
182	  }
183	  ctx.initialized = true;
184	  printf("[INFO] InitEngine %s success\n", ctx.name);
185	  uint8_t *dev_ptr = nullptr;
186	  CHECK_ACL(aclrtMalloc(reinterpret_cast<void **>(&dev_ptr), kBufferSize, ACL_MEM_MALLOC_HUGE_ONLY));
187	  ctx.dev_buf = dev_ptr;
188	  CHECK_ACL(aclrtMallocHost(&ctx.host_buf, kBufferSize));
189	  std::fill(static_cast<uint8_t *>(ctx.host_buf), static_cast<uint8_t *>(ctx.host_buf) + kBufferSize, 0);
190	  MemDesc desc{};
191	  desc.addr = reinterpret_cast<uintptr_t>(ctx.dev_buf);
192	  desc.len = kBufferSize;
193	  ret = ctx.engine.RegisterMem(desc, MEM_DEVICE, ctx.dev_handle);
194	  if (ret != SUCCESS) {
195	    printf("[ERROR] %s RegisterMem device failed, ret=%u, errmsg:%s\n", ctx.name, ret, GetRecentErrMsg());
196	    return -1;
197	  }
198	  desc.addr = reinterpret_cast<uintptr_t>(ctx.host_buf);
199	  ret = ctx.engine.RegisterMem(desc, MEM_HOST, ctx.host_handle);
200	  if (ret != SUCCESS) {
201	    printf("[ERROR] %s RegisterMem host failed, ret=%u, errmsg:%s\n", ctx.name, ret, GetRecentErrMsg());
202	    return -1;
203	  }
204	  std::fill(static_cast<uint8_t *>(ctx.host_buf), static_cast<uint8_t *>(ctx.host_buf) + kBufferSize, fill_value);
205	  CHECK_ACL(aclrtMemcpy(ctx.dev_buf, kBufferSize, ctx.host_buf, kBufferSize, ACL_MEMCPY_HOST_TO_DEVICE));
206	  printf("[INFO] %s InitEngine success, dev:%p, host:%p\n", ctx.name, ctx.dev_buf, ctx.host_buf);
207	  return 0;
208	}
209	
210	int32_t Connect(EngineCtx &ctx_a, EngineCtx &ctx_b) {
211	  auto ret = ctx_a.engine.ConnectAsync(ctx_b.name, kConnTimeout);
212	  if (ret != SUCCESS) {
213	    printf("[ERROR] ConnectAsync %s->%s failed, ret=%u, errmsg:%s\n", ctx_a.name, ctx_b.name, ret, GetRecentErrMsg());
214	    return -1;
215	  }
216	  ret = ctx_b.engine.ConnectAsync(ctx_a.name, kConnTimeout);
217	  if (ret != SUCCESS) {
218	    printf("[ERROR] ConnectAsync %s->%s failed, ret=%u, errmsg:%s\n", ctx_b.name, ctx_a.name, ret, GetRecentErrMsg());
219	    return -1;
220	  }
221	  AsyncConnectStatus status_a = AsyncConnectStatus::NOT_CONNECT;
222	  AsyncConnectStatus status_b = AsyncConnectStatus::NOT_CONNECT;
223	  while (status_a != AsyncConnectStatus::CONNECTED || status_b != AsyncConnectStatus::CONNECTED) {
224	    ctx_a.engine.GetAsyncConnectStatus(ctx_b.name, status_a);
225	    ctx_b.engine.GetAsyncConnectStatus(ctx_a.name, status_b);
226	    if (status_a == AsyncConnectStatus::CONNECT_FAILED || status_b == AsyncConnectStatus::CONNECT_FAILED) {
227	      printf("[ERROR] Connect failed, status_a=%d, status_b=%d\n", static_cast<int>(status_a),
228	             static_cast<int>(status_b));
229	      return -1;
230	    }
231	    std::this_thread::sleep_for(std::chrono::milliseconds(10));
232	  }
233	  ctx_a.connected = true;
234	  ctx_b.connected = true;
235	  printf("[INFO] Connect success\n");
236	  return 0;
237	}
238	
239	void BuildTransferDescs(std::vector<TransferOpDesc> &descs, EngineCtx &ctx_a, EngineCtx &ctx_b) {
240	  descs.reserve(kChunkCount);
241	  for (size_t i = 0; i < kChunkCount; ++i) {
242	    TransferOpDesc desc{};
243	    desc.local_addr = reinterpret_cast<uintptr_t>(ctx_a.dev_buf) + i * kChunkSize;
244	    desc.remote_addr = reinterpret_cast<uintptr_t>(ctx_b.host_buf) + i * kChunkSize;
245	    desc.len = kChunkSize;
246	    descs.push_back(desc);
247	  }
248	}
249	
250	int32_t StartTransfers(EngineCtx &ctx_a, EngineCtx &ctx_b, std::vector<TransferOpDesc> &descs, TransferReq &req_a,
251	                       TransferReq &req_b) {
252	  TransferArgs args{};
253	  req_a = nullptr;
254	  auto ret = ctx_a.engine.TransferAsync(ctx_b.name, WRITE, descs, args, req_a);
255	  if (ret != SUCCESS) {
256	    printf("[ERROR] TransferAsync %s->%s failed, ret=%u, errmsg:%s\n", ctx_a.name, ctx_b.name, ret, GetRecentErrMsg());
257	    return -1;
258	  }
259	
260	  // Update descriptors for B->A transfer
261	  for (size_t i = 0; i < kChunkCount; ++i) {
262	    descs[i].local_addr = reinterpret_cast<uintptr_t>(ctx_b.dev_buf) + i * kChunkSize;
263	    descs[i].remote_addr = reinterpret_cast<uintptr_t>(ctx_a.host_buf) + i * kChunkSize;
264	  }
265	
266	  req_b = nullptr;
267	  ret = ctx_b.engine.TransferAsync(ctx_a.name, WRITE, descs, args, req_b);
268	  if (ret != SUCCESS) {
269	    printf("[ERROR] TransferAsync %s->%s failed, ret=%u, errmsg:%s\n", ctx_b.name, ctx_a.name, ret, GetRecentErrMsg());
270	    return -1;
271	  }
272	  return 0;
273	}
274	
275	int32_t WaitTransfers(EngineCtx &ctx_a, EngineCtx &ctx_b, TransferReq req_a, TransferReq req_b) {
276	  TransferStatus st_a = TransferStatus::WAITING;
277	  TransferStatus st_b = TransferStatus::WAITING;
278	  int32_t poll_count = 0;
279	  while (st_a == TransferStatus::WAITING || st_b == TransferStatus::WAITING) {
280	    if (st_a == TransferStatus::WAITING) {
281	      ctx_a.engine.GetTransferStatus(req_a, st_a);
282	    }
283	    if (st_b == TransferStatus::WAITING) {
284	      ctx_b.engine.GetTransferStatus(req_b, st_b);
285	    }
286	    if (++poll_count > kMaxPollCount) {
287	      printf("[ERROR] Transfer poll timeout\n");
288	      return -1;
289	    }
290	    std::this_thread::sleep_for(std::chrono::microseconds(100));
291	  }
292	  if (st_a != TransferStatus::COMPLETED) {
293	    printf("[ERROR] Transfer %s->%s failed, status=%d\n", ctx_a.name, ctx_b.name, static_cast<int>(st_a));
294	    return -1;
295	  }
296	  if (st_b != TransferStatus::COMPLETED) {
297	    printf("[ERROR] Transfer %s->%s failed, status=%d\n", ctx_b.name, ctx_a.name, static_cast<int>(st_b));
298	    return -1;
299	  }
300	  printf("[INFO] Transfer completed\n");
301	  return 0;
302	}
303	
304	int32_t Transfer(EngineCtx &ctx_a, EngineCtx &ctx_b) {
305	  std::vector<TransferOpDesc> descs;
306	  BuildTransferDescs(descs, ctx_a, ctx_b);
307	  TransferReq req_a = nullptr;
308	  TransferReq req_b = nullptr;
309	  if (StartTransfers(ctx_a, ctx_b, descs, req_a, req_b) != 0) {
310	    return -1;
311	  }
312	  return WaitTransfers(ctx_a, ctx_b, req_a, req_b);
313	}
314	
315	int32_t Verify(EngineCtx &ctx_a, EngineCtx &ctx_b) {
316	  std::vector<uint8_t> expected_a(kBufferSize, kFillA);
317	  std::vector<uint8_t> expected_b(kBufferSize, kFillB);
318	  if (std::memcmp(ctx_b.host_buf, expected_a.data(), kBufferSize) != 0) {
319	    printf("[ERROR] Verify %s host failed, expected 0xAA\n", ctx_b.name);
320	    return -1;
321	  }
322	  if (std::memcmp(ctx_a.host_buf, expected_b.data(), kBufferSize) != 0) {
323	    printf("[ERROR] Verify %s host failed, expected 0xBB\n", ctx_a.name);
324	    return -1;
325	  }
326	  printf("[INFO] Verify success\n");
327	  return 0;
328	}
329	
330	void DisconnectBoth(EngineCtx &ctx_a, EngineCtx &ctx_b) {
331	  if (ctx_a.connected) {
332	    auto ret = ctx_a.engine.DisconnectAsync(ctx_b.name, kConnTimeout);
333	    if (ret != SUCCESS) {
334	      printf("[ERROR] DisconnectAsync %s->%s failed, ret=%u, errmsg:%s\n", ctx_a.name, ctx_b.name, ret,
335	             GetRecentErrMsg());
336	    }
337	  }
338	  if (ctx_b.connected) {
339	    auto ret = ctx_b.engine.DisconnectAsync(ctx_a.name, kConnTimeout);
340	    if (ret != SUCCESS) {
341	      printf("[ERROR] DisconnectAsync %s->%s failed, ret=%u, errmsg:%s\n", ctx_b.name, ctx_a.name, ret,
342	             GetRecentErrMsg());
343	    }
344	  }
345	  if (ctx_a.connected || ctx_b.connected) {
346	    AsyncConnectStatus st_a = AsyncConnectStatus::DISCONNECT_PENDING;
347	    AsyncConnectStatus st_b = AsyncConnectStatus::DISCONNECT_PENDING;
348	    while (st_a != AsyncConnectStatus::NOT_CONNECT || st_b != AsyncConnectStatus::NOT_CONNECT) {
349	      ctx_a.engine.GetAsyncConnectStatus(ctx_b.name, st_a);
350	      ctx_b.engine.GetAsyncConnectStatus(ctx_a.name, st_b);
351	      std::this_thread::sleep_for(std::chrono::milliseconds(10));
352	    }
353	    printf("[INFO] Disconnect success\n");
354	  }
355	}
356	
357	void CleanupResources(EngineCtx &ctx) {
358	  if (ctx.dev_handle != nullptr) {
359	    ctx.engine.DeregisterMem(ctx.dev_handle);
360	  }
361	  if (ctx.host_handle != nullptr) {
362	    ctx.engine.DeregisterMem(ctx.host_handle);
363	  }
364	  if (ctx.dev_buf != nullptr) {
365	    CHECK_ACL(aclrtFree(ctx.dev_buf));
366	  }
367	  if (ctx.host_buf != nullptr) {
368	    CHECK_ACL(aclrtFreeHost(ctx.host_buf));
369	  }
370	}
371	
372	void ShutdownEngines(EngineCtx &ctx_a, EngineCtx &ctx_b) {
373	  if (ctx_a.initialized) {
374	    ctx_a.engine.Finalize();
375	  }
376	  if (ctx_b.initialized) {
377	    ctx_b.engine.Finalize();
378	  }
379	}
380	
381	void RestoreDevices(EngineCtx &ctx_a, EngineCtx &ctx_b) {
382	  CHECK_ACL(aclrtResetDevice(ctx_a.device_id));
383	  CHECK_ACL(aclrtResetDevice(ctx_b.device_id));
384	}
385	
386	void Finalize(EngineCtx &ctx_a, EngineCtx &ctx_b) {
387	  DisconnectBoth(ctx_a, ctx_b);
388	  CleanupResources(ctx_a);
389	  CleanupResources(ctx_b);
390	  ShutdownEngines(ctx_a, ctx_b);
391	  RestoreDevices(ctx_a, ctx_b);
392	}
393	
394	int32_t Run(EngineCtx &ctx_a, EngineCtx &ctx_b, const std::vector<std::string> &protocols, int32_t version) {
395	  if (InitEngine(ctx_a, protocols, version, kFillA) != 0) {
396	    return -1;
397	  }
398	  if (InitEngine(ctx_b, protocols, version, kFillB) != 0) {
399	    return -1;
400	  }
401	  if (Connect(ctx_a, ctx_b) != 0) {
402	    return -1;
403	  }
404	  if (Transfer(ctx_a, ctx_b) != 0) {
405	    return -1;
406	  }
407	  return Verify(ctx_a, ctx_b);
408	}
409	}  // namespace
410	
411	int main(int32_t argc, char **argv) {
412	  std::vector<std::string> protocols;
413	  int32_t version = 1;
414	  int32_t device_a = kDefaultDevA;
415	  int32_t device_b = kDefaultDevB;
416	
417	  if (ParseArgs(argc, argv, device_a, device_b, protocols, version) != 0) {
418	    return -1;
419	  }
420	
421	  EngineCtx ctx_a;
422	  EngineCtx ctx_b;
423	
424	  ctx_a.name = kEngineA;
425	  ctx_a.device_id = device_a;
426	  ctx_b.name = kEngineB;
427	  ctx_b.device_id = device_b;
428	
429	  int32_t ret = Run(ctx_a, ctx_b, protocols, version);
430	  Finalize(ctx_a, ctx_b);
431	  return ret;
432	}
