137	  if (protocols.empty()) {
138	    printf("[ERROR] --protocol is required\n");
139	    return -1;
140	  }
141	  ctx.is_client = (role == "client");
142	  for (const auto &p : protocols) {
143	    if (ValidateProtoName(p) != 0) {
144	      return -1;
145	    }
146	  }
147	  if (version == kVersionLegacy &&
148	      (protocols.size() != 1 || (protocols[0] != "roce:device" && protocols[0] != "hccs:device"))) {
149	    printf("[ERROR] version 0 only supports roce:device and hccs:device\n");
150	    return -1;
151	  }
152	  if (ParsePort(ctx.local_engine) < 0 || ParsePort(ctx.remote_engine) < 0) {
153	    printf("[ERROR] Invalid engine address format, expected ip:port\n");
154	    return -1;
155	  }
156	  return 0;
157	}
158	
159	int32_t ParseArgs(int32_t argc, char **argv, EngineCtx &ctx, std::vector<std::string> &protocols, int32_t &version) {
160	  std::string role;
161	  int32_t device_id = -1;
162	  std::string local_engine;
163	  std::string remote_engine;
164	
165	  // Parse all command line arguments
166	  for (int32_t i = 1; i < argc; ++i) {
167	    if (ParseSingleArg(argv[i], role, device_id, local_engine, remote_engine, protocols, version, argv[0]) != 0) {
168	      return -1;
169	    }
170	  }
171	
172	  // Set context based on role
173	  ctx.is_client = (role == "client");
174	  ctx.device_id = (device_id >= 0) ? device_id : (ctx.is_client ? kDefaultDeviceClient : kDefaultDeviceServer);
175	  ctx.local_engine =
176	      local_engine.empty() ? (ctx.is_client ? kDefaultClientEngine : kDefaultServerEngine) : local_engine;
177	  ctx.remote_engine =
178	      remote_engine.empty() ? (ctx.is_client ? kDefaultServerEngine : kDefaultClientEngine) : remote_engine;
179	
180	  // Validate all parameters
181	  if (ValidateArgs(role, protocols, version, ctx) != 0) {
182	    return -1;
183	  }
184	
185	  // Display final configuration
186	  printf("[INFO] ParseArgs: role=%s, device=%d\n", role.c_str(), ctx.device_id);
187	  printf("[INFO]   local=%s, remote=%s\n", ctx.local_engine.c_str(), ctx.remote_engine.c_str());
188	  printf("[INFO]   version=%d\n", version);
189	  for (const auto &p : protocols) {
190	    printf("[INFO]   protocol: %s\n", p.c_str());
191	  }
192	  return 0;
193	}
194	
195	int32_t PrepareLegacyOpts(const std::vector<std::string> &protocols, std::map<AscendString, AscendString> &options) {
196	  printf("[INFO] Using legacy flow (version=0)\n");
197	  std::string local_comm_res = "{\"version\": \"1.2\"}";
198	  options[OPTION_LOCAL_COMM_RES] = local_comm_res.c_str();
199	  options[OPTION_BUFFER_POOL] = "0:0";
200	  if (protocols[0] == "roce:device") {
201	    setenv("HCCL_INTRA_ROCE_ENABLE", "1", 1);
202	  }
203	  return 0;
204	}
205	
206	int32_t PrepareV2Opts(const std::vector<std::string> &protocols, std::map<AscendString, AscendString> &options) {
207	  std::string desc_array;
208	  for (size_t i = 0; i < protocols.size(); ++i) {
209	    if (i > 0) {
210	      desc_array += ",";
211	    }
212	    desc_array += "\"" + protocols[i] + "\"";
213	  }
214	  std::string resource_config = "{\"comm_resource_config.protocol_desc\": [" + desc_array + "]}";
215	  options[OPTION_GLOBAL_RESOURCE_CONFIG] = resource_config.c_str();
216	  return 0;
217	}
218	
219	int32_t InitEngine(EngineCtx &ctx, const std::vector<std::string> &protocols, int32_t version) {
220	  CHECK_ACL(aclrtSetDevice(ctx.device_id));
221	  std::map<AscendString, AscendString> options;
222	  if (version == kVersionLegacy) {
223	    PrepareLegacyOpts(protocols, options);
224	  } else {
225	    PrepareV2Opts(protocols, options);
226	  }
227	  auto ret = ctx.engine.Initialize(ctx.local_engine.c_str(), options);
228	  if (ret != SUCCESS) {
229	    printf("[ERROR] Initialize failed, ret=%u, errmsg:%s\n", ret, GetRecentErrMsg());
230	    return -1;
231	  }
232	  ctx.initialized = true;
233	  uint8_t *dev_ptr = nullptr;
234	  CHECK_ACL(aclrtMalloc(reinterpret_cast<void **>(&dev_ptr), kBufSize, ACL_MEM_MALLOC_HUGE_ONLY));
235	  ctx.dev_buf = dev_ptr;
236	  MemDesc desc{};
237	  desc.addr = reinterpret_cast<uintptr_t>(ctx.dev_buf);
238	  desc.len = kBufSize;
239	  ret = ctx.engine.RegisterMem(desc, MEM_DEVICE, ctx.dev_handle);
240	  if (ret != SUCCESS) {
241	    printf("[ERROR] RegisterMem failed, ret=%u, errmsg:%s\n", ret, GetRecentErrMsg());
242	    return -1;
243	  }
244	  if (!ctx.is_client) {
245	    std::vector<uint8_t> fill_data(kBufSize, kFillValue);
246	    CHECK_ACL(aclrtMemcpy(ctx.dev_buf, kBufSize, fill_data.data(), kBufSize, ACL_MEMCPY_HOST_TO_DEVICE));
247	  }
248	  printf("[INFO] InitEngine success, dev:%p\n", ctx.dev_buf);
249	  return 0;
250	}
251	
252	int32_t GetRemoteAddr(EngineCtx &ctx) {
253	  int port = ParsePort(ctx.remote_engine) + kSocketPortOffset;
254	  std::string ip = ctx.remote_engine.substr(0, ctx.remote_engine.find(':'));
255	  int fd = -1;
256	  for (int32_t retry = 0; retry < kSocketRetryCount; ++retry) {
257	    fd = socket(AF_INET, SOCK_STREAM, 0);
258	    struct sockaddr_in addr {};
259	    addr.sin_family = AF_INET;
260	    addr.sin_port = htons(static_cast<uint16_t>(port));
261	    inet_pton(AF_INET, ip.c_str(), &addr.sin_addr);
262	    if (connect(fd, reinterpret_cast<struct sockaddr *>(&addr), sizeof(addr)) == 0) {
263	      break;
264	    }
265	    close(fd);
266	    fd = -1;
267	    if (retry + 1 < kSocketRetryCount) {
268	      printf("[INFO] Connect retry %d/%d...\n", retry + 1, kSocketRetryCount);
269	      usleep(kSocketRetryIntervalUs);
270	    }
271	  }
272	  if (fd < 0) {
273	    printf("[ERROR] Failed to connect to server on port %d\n", port);
274	    return -1;
275	  }
276	  ssize_t received = 0;
277	  while (received < static_cast<ssize_t>(sizeof(ctx.remote_addr))) {
278	    ssize_t n = recv(fd, reinterpret_cast<char *>(&ctx.remote_addr) + received, sizeof(ctx.remote_addr) - received, 0);
279	    if (n <= 0) {
280	      printf("[ERROR] recv failed\n");
281	      close(fd);
282	      return -1;
283	    }
284	    received += n;
285	  }
286	  ctx.conn_fd = fd;
287	  printf("[INFO] GetRemoteAddr success, remote_addr:%p\n", reinterpret_cast<void *>(ctx.remote_addr));
288	  return 0;
289	}
290	
291	int32_t Connect(EngineCtx &ctx) {
292	  auto ret = ctx.engine.Connect(ctx.remote_engine.c_str(), kConnectTimeout);
293	  if (ret != SUCCESS) {
294	    printf("[ERROR] Connect failed, ret=%u, errmsg:%s\n", ret, GetRecentErrMsg());
295	    return -1;
296	  }
297	  ctx.connected = true;
298	  printf("[INFO] Connect success\n");
299	  return 0;
300	}
301	
302	int32_t Transfer(EngineCtx &ctx) {
303	  std::vector<TransferOpDesc> descs;
304	  descs.reserve(kBlockCount);
305	  for (size_t i = 0; i < kBlockCount; ++i) {
306	    TransferOpDesc desc{};
307	    desc.local_addr = reinterpret_cast<uintptr_t>(ctx.dev_buf) + i * kBlockSize;
308	    desc.remote_addr = ctx.remote_addr + i * kBlockSize;
309	    desc.len = kBlockSize;
310	    descs.push_back(desc);
311	  }
312	  auto ret = ctx.engine.TransferSync(ctx.remote_engine.c_str(), READ, descs, kTransferTimeout);
313	  if (ret != SUCCESS) {
314	    printf("[ERROR] TransferSync READ failed, ret=%u, errmsg:%s\n", ret, GetRecentErrMsg());
315	    return -1;
316	  }
317	  printf("[INFO] TransferSync READ completed\n");
318	  return 0;
319	}
320	
321	int32_t Verify(EngineCtx &ctx) {
322	  void *host_tmp = nullptr;
323	  CHECK_ACL(aclrtMallocHost(&host_tmp, kBufSize));
324	  CHECK_ACL(aclrtMemcpy(host_tmp, kBufSize, ctx.dev_buf, kBufSize, ACL_MEMCPY_DEVICE_TO_HOST));
325	  std::vector<uint8_t> expected(kBufSize, kFillValue);
326	  if (std::memcmp(host_tmp, expected.data(), kBufSize) != 0) {
327	    printf("[ERROR] Verify failed, data mismatch\n");
328	    CHECK_ACL(aclrtFreeHost(host_tmp));
329	    return -1;
330	  }
331	  CHECK_ACL(aclrtFreeHost(host_tmp));
332	  printf("[INFO] Verify success\n");
333	  return 0;
334	}
335	
336	int32_t SetupListenSocket(EngineCtx &ctx, int port) {
337	  ctx.listen_fd = socket(AF_INET, SOCK_STREAM, 0);
338	  if (ctx.listen_fd < 0) {
339	    printf("[ERROR] socket() failed\n");
340	    return -1;
341	  }
342	  int opt = 1;
343	  setsockopt(ctx.listen_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));
344	  struct sockaddr_in addr {};
345	  addr.sin_family = AF_INET;
346	  addr.sin_addr.s_addr = htonl(INADDR_ANY);
347	  addr.sin_port = htons(static_cast<uint16_t>(port));
348	  if (bind(ctx.listen_fd, reinterpret_cast<struct sockaddr *>(&addr), sizeof(addr)) < 0) {
349	    printf("[ERROR] bind port %d failed\n", port);
350	    close(ctx.listen_fd);
351	    ctx.listen_fd = -1;
352	    return -1;
353	  }
354	  if (listen(ctx.listen_fd, kSocketBacklog) < 0) {
355	    printf("[ERROR] listen failed\n");
356	    close(ctx.listen_fd);
357	    ctx.listen_fd = -1;
358	    return -1;
359	  }
360	  return 0;
361	}
362	
363	int32_t AcceptAndSendAddr(EngineCtx &ctx) {
364	  ctx.conn_fd = accept(ctx.listen_fd, nullptr, nullptr);
365	  if (ctx.conn_fd < 0) {
366	    printf("[ERROR] accept failed\n");
367	    return -1;
368	  }
369	  uintptr_t buf_addr = reinterpret_cast<uintptr_t>(ctx.dev_buf);
370	  ssize_t sent = 0;
371	  while (sent < static_cast<ssize_t>(sizeof(buf_addr))) {
372	    ssize_t n = send(ctx.conn_fd, reinterpret_cast<const char *>(&buf_addr) + sent, sizeof(buf_addr) - sent, 0);
373	    if (n <= 0) {
374	      printf("[ERROR] send failed\n");
375	      close(ctx.conn_fd);
376	      ctx.conn_fd = -1;
377	      return -1;
378	    }
379	    sent += n;
380	  }
381	  printf("[INFO] Sent buffer addr %p to client, waiting for client to finish...\n", reinterpret_cast<void *>(buf_addr));
382	  return 0;
383	}
384	
385	void WaitForClientDisconnect(EngineCtx &ctx) {
386	  char dummy;
387	  ssize_t recv_ret = 1;
388	  while (recv_ret > 0) {
389	    recv_ret = recv(ctx.conn_fd, &dummy, 1, 0);
390	  }
391	  printf("[INFO] Client disconnected, server exiting\n");
392	}
393	
394	int32_t ServerSendAddr(EngineCtx &ctx) {
395	  int port = ParsePort(ctx.local_engine) + kSocketPortOffset;
396	  if (SetupListenSocket(ctx, port) != 0) {
397	    return -1;
398	  }
399	  printf("[INFO] Waiting for client on port %d...\n", port);
400	  if (AcceptAndSendAddr(ctx) != 0) {
401	    return -1;
402	  }
403	  WaitForClientDisconnect(ctx);
404	  return 0;
405	}
406	
407	void Finalize(EngineCtx &ctx) {
408	  if (ctx.connected) {
409	    auto ret = ctx.engine.Disconnect(ctx.remote_engine.c_str(), kConnectTimeout);
410	    if (ret != SUCCESS) {
411	      printf("[ERROR] Disconnect failed, ret=%u, errmsg:%s\n", ret, GetRecentErrMsg());
412	    } else {
413	      printf("[INFO] Disconnect success\n");
414	    }
415	  }
416	  if (ctx.conn_fd >= 0) {
417	    close(ctx.conn_fd);
418	  }
419	  if (ctx.listen_fd >= 0) {
420	    close(ctx.listen_fd);
421	  }
422	  if (ctx.dev_handle != nullptr) {
423	    ctx.engine.DeregisterMem(ctx.dev_handle);
424	    printf("[INFO] DeregisterMem success\n");
425	  }
426	  if (ctx.dev_buf != nullptr) {
427	    CHECK_ACL(aclrtFree(ctx.dev_buf));
428	    printf("[INFO] Free memory success\n");
429	  }
430	  if (ctx.initialized) {
431	    ctx.engine.Finalize();
432	    printf("[INFO] Finalize success\n");
433	  }
434	  CHECK_ACL(aclrtResetDevice(ctx.device_id));
435	}
436	int32_t Run(EngineCtx &ctx, const std::vector<std::string> &protocols, int32_t version) {
437	  if (InitEngine(ctx, protocols, version) != 0) {
438	    return -1;
439	  }
440	  if (ctx.is_client) {
441	    if (GetRemoteAddr(ctx) != 0) {
442	      return -1;
443	    }
444	    if (Connect(ctx) != 0) {
445	      return -1;
446	    }
447	    if (Transfer(ctx) != 0) {
448	      return -1;
449	    }
450	    if (Verify(ctx) != 0) {
451	      return -1;
452	    }
453	  } else {
454	    if (ServerSendAddr(ctx) != 0) {
455	      return -1;
456	    }
457	  }
458	  return 0;
459	}
460	}  // namespace
461	
462	int main(int32_t argc, char **argv) {
463	  EngineCtx ctx;
464	  std::vector<std::string> protocols;
465	  int32_t version = 1;
466	  if (ParseArgs(argc, argv, ctx, protocols, version) != 0) {
467	    return -1;
468	  }
469	  int32_t ret = Run(ctx, protocols, version);
470	  Finalize(ctx);
471	  return ret;
472	}
